import{_ as o,l as i,o as e,c as s,v as l,p as n,x as t,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"Maglev","description":"","frontmatter":{"title":"Maglev","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/maglev-lb.md","filePath":"cs/maglev-lb.md","lastUpdated":1789023840000}'),c={name:"cs/maglev-lb.md"};function m(E,a,_,g,u,v){const r=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=l('<h1 id="maglev" tabindex="-1">Maglev <a class="header-anchor" href="#maglev" aria-label="Permalink to &quot;Maglev&quot;">​</a></h1><div class="epigraph"><p>用一致性哈希表把五元组映到后端，后端增减时尽量少打断已有连接；查找是一次内存访问量级。</p><footer>—— 据 Eisenbud et al., Maglev, NSDI 2016 整理</footer></div><p><a href="/cs/l4-l7-load-balancing">上一课</a> 要选后端。<a href="/cs/ecmp-hashing">ECMP</a> 哈希会在成员变化时大迁移。缺口是 <strong>Maglev 一致性哈希</strong>：查找表、后端故障。本课不把反向代理写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>ECMP 成员 down 几乎重哈希所有流。Maglev：为每个后端生成置换，填一张大表，查哈希(五元组) mod 表长。增减后端只扰动部分表项，连接尽量留。与 QUIC CID：可用 CID 当键，迁移后仍粘同一后端。L7 仍可在 Maglev 后再做。</p><p>不要把论文当唯一实现；思想是稳定哈希。</p><p><span class="marginnote">NSDI 2016。Google 生产。本课不抄表填充伪代码考试。</span></p><h3 id="稳定哈希减扰动" tabindex="-1">稳定哈希减扰动 <a class="header-anchor" href="#稳定哈希减扰动" aria-label="Permalink to &quot;稳定哈希减扰动&quot;">​</a></h3><p>成员变化只动部分连接。键可以是 CID。无健康检查会稳定打到尸体。极化仍可能。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照：取模哈希 / 一致性哈希 / Maglev 表。画：键 → 表项 → 后端。与 Kademlia DHT 的一致性哈希同族，一层 LB，一层 P2P。</p>',11)),(e(),n(h,null,{default:t(()=>[p(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20KEY%5B%22%E4%BA%94%E5%85%83%E7%BB%84%E6%88%96%20CID%22%5D%20--%3E%20TAB%5B%22Maglev%20%E6%9F%A5%E6%89%BE%E8%A1%A8%22%5D%0A%20%20TAB%20--%3E%20BE%5B%22%E5%90%8E%E7%AB%AF%22%5D%0A%20%20CHG%5B%22%E5%90%8E%E7%AB%AF%E5%A2%9E%E5%87%8F%22%5D%20--%3E%20SMALL%5B%22%E5%B0%91%E9%87%8F%E8%A1%A8%E9%A1%B9%E5%8F%98%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>健康检查更新表，与 BGP 撤回同类：控制面变，数据面查新表。极化仍可能。数据中心 Clos 上 Maglev 常在入口。RPKI 无。</p><p>失败：表未及时更新会打到死后端，要探测。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 Ketama 的全部变体。反向代理是下一课。后课默认：Maglev 式表提供稳定 L4 映射。</p><p>无健康检查的一致性哈希会稳定地打到尸体。</p><p>上一课留下的缺口在本课收口；「Maglev」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/reverse-proxy">反向代理</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>一致性哈希减少成员变化时的扰动。</li><li>表查找线速。</li><li>键可从五元组扩展到 CID。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：Eisenbud et al., NSDI 2016。</li></ul>',10))])}const b=o(c,[["render",m]]);export{f as __pageData,b as default};
